            sandbox.apply_force(agent_body, (-150, 0))
    elif 11.75 <= pos[0] <= 12.5:
        # Adjust speed for gate 3 and gate 4 timing
        if vel[0] > 2.5:
            sandbox.apply_force(agent_body, (-100, 0))

    return

