    pos = sandbox.get_vehicle_position()
    vel = sandbox.get_vehicle_velocity()

    # Speed trap at x=9.0 m
    if 8.9 <= pos[0] <= 9.1:
        if vel[0] < 2.8:
            sandbox.apply_force(agent_body, (100, 0))

    # Checkpoint at x=11.0 m
    if 10.9 <= pos[0] <= 11.1:
        if vel[0] < 1.1:
            sandbox.apply_force(agent_body, (50, 0))
        elif vel[0] > 2.7:
            sandbox.apply_force(agent_body, (-50, 0))

    # First impulse zone (x=8.0-9.0 m)
    if 8.0 <= pos[0] <= 9.0:
        distance_to_gate1 = 10.0 - pos[0]
        time_to_gate1 = distance_to_gate1 / vel[0]
        # Gate 1 open window: t ∈ [0.35, 0.97] s
        if time_to_gate1 < 0.35:
            sandbox.apply_force(agent_body, (-50, 0))
        elif time_to_gate1 > 0.97:
            sandbox.apply_force(agent_body, (50, 0))

    # Second impulse zone (x=10.5-11.0 m)
    if 10.5 <= pos[0] <= 11.0:
        distance_to_gate2 = 11.5 - pos[0]
        time_to_gate2 = distance_to_gate2 / vel[0]
        # Gate 2 open window: t ∈ [0, 4.21] s
        # Ensure time_to_gate2 is within 0.5 to 3.0 s
        if time_to_gate2 < 0.5:
            sandbox.apply_force(agent_body, (-50, 0))
        elif time_to_gate2 > 3.0:
            sandbox.apply_force(agent_body, (50, 0))

    # Third gate (x=11.75 m)
    if 11.5 <= pos[0] <= 12.0:
        distance_to_gate3 = 11.75 - pos[0]
        time_to_gate3 = distance_to_gate3 / vel[0]
        # Gate 3 open window: t ∈ [0.81, 1.81] s
        if time_to_gate3 < 0.81:
            sandbox.apply_force(agent_body, (-50, 0))
        elif time_to_gate3 > 1.81:
            sandbox.apply_force(agent_body, (50, 0))

    # Brake zone (x=12.0-15.0 m) for final speed tuning
    if 12.0 <= pos[0] <= 15.0:
        if vel[0] > 1.5:
            sandbox.apply_force(agent_body, (-100, 0))

    return
